from math import factorial


def count_k_palindromic_numbers(n: int, k: int) -> int:
    """Count n-digit integers whose digits can form a k-divisible palindrome."""
    half_len = (n + 1) // 2
    signatures = set()

    for half in range(10 ** (half_len - 1), 10 ** half_len):
        prefix = str(half)
        if n % 2:
            palindrome = prefix + prefix[:-1][::-1]
        else:
            palindrome = prefix + prefix[::-1]
        if int(palindrome) % k == 0:
            counts = [0] * 10
            for digit in palindrome:
                counts[ord(digit) - ord("0")] += 1
            signatures.add(tuple(counts))

    total = 0
    n_factorial = factorial(n)
    leading_factorial = factorial(n - 1)
    for counts in signatures:
        arrangements = n_factorial
        for count in counts:
            arrangements //= factorial(count)

        if counts[0]:
            with_leading_zero = leading_factorial // factorial(counts[0] - 1)
            for count in counts[1:]:
                with_leading_zero //= factorial(count)
            arrangements -= with_leading_zero
        total += arrangements

    return total

