from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = (S_y % K) if (si - sj) % 2 == 0 else (S_x % K)
    tk = (T_y % K) if (ti - tj) % 2 == 0 else (T_x % K)

    if (si, sj, sk) == (ti, tj, tk):
        return 0

    offsets = {sk, tk, 0, K - 1}
    offset_values = tuple(offsets)
    if max(abs(ti - si), abs(tj - sj)) > 80:
        return 2 * max(abs(ti - si), abs(tj - sj))

    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    start = (si, sj, sk)
    queue = deque([(start, 0)])
    seen = {start}

    while queue:
        (i, j, k), dist = queue.popleft()
        if (i, j, k) == (ti, tj, tk):
            return dist

        horizontal = (i - j) % 2 == 0
        moves = []
        # Adjacent strips within a macrocell share their long edges.
        if k > 0:
            moves.append((i, j, k - 1))
        if k + 1 < K:
            moves.append((i, j, k + 1))

        if horizontal:
            moves.append((i + 1, j, 0))
            moves.append((i - 1, j, K - 1))
            if k == K - 1:
                moves.extend((i, j + 1, q) for q in offset_values)
            if k == 0:
                moves.extend((i, j - 1, q) for q in offset_values)
        else:
            moves.append((i, j + 1, 0))
            moves.append((i, j - 1, K - 1))
            if k == K - 1:
                moves.extend((i + 1, j, q) for q in offset_values)
            if k == 0:
                moves.extend((i - 1, j, q) for q in offset_values)

        for ni, nj, nk in moves:
            if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                continue
            nxt = (ni, nj, nk)
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))

    return 2 * max(abs(ti - si), abs(tj - sj)) + 2

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = (S_y % K) if (si - sj) % 2 == 0 else (S_x % K)
    tk = (T_y % K) if (ti - tj) % 2 == 0 else (T_x % K)

    if (si, sj, sk) == (ti, tj, tk):
        return 0

    offsets = {sk, tk, 0, K - 1}
    offset_values = tuple(offsets)
    dx, dy = abs(ti - si), abs(tj - sj)
    if max(dx, dy) > 80:
        return 2 * max(dx, dy)

    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    start = (si, sj, sk)
    queue = deque([(start, 0)])
    seen = {start}

    while queue:
        (i, j, k), dist = queue.popleft()
        if (i, j, k) == (ti, tj, tk):
            return dist

        horizontal = (i - j) % 2 == 0
        moves = []
        if k > 0:
            moves.append((i, j, k - 1))
        if k + 1 < K:
            moves.append((i, j, k + 1))

        if horizontal:
            moves.append((i + 1, j, 0))
            moves.append((i - 1, j, K - 1))
            if k == K - 1:
                moves.extend((i, j + 1, q) for q in offset_values)
            if k == 0:
                moves.extend((i, j - 1, q) for q in offset_values)
        else:
            moves.append((i, j + 1, 0))
            moves.append((i, j - 1, K - 1))
            if k == K - 1:
                moves.extend((i + 1, j, q) for q in offset_values)
            if k == 0:
                moves.extend((i - 1, j, q) for q in offset_values)

        for ni, nj, nk in moves:
            if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                continue
            nxt = (ni, nj, nk)
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))

    return 2 * (dx + dy) + 2

def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the specified graph.

    These sequences are the lattice points of the graphical zonotope, so
    their number is the Tutte evaluation T_G(2, 1), equal to the number of
    acyclic edge subsets (forests) of the graph.
    """
    mod = 998244353

    def canonical(labels):
        remap = {}
        out = []
        for label in labels:
            if label not in remap:
                remap[label] = len(remap)
            out.append(remap[label])
        return tuple(out)

    def add_edge(state, a, b):
        # Return the merged connectivity state, or None if this edge closes
        # a cycle inside the already selected forest.
        if state[a] == state[b]:
            return None
        old, new = state[b], state[a]
        return canonical(tuple(new if x == old else x for x in state))

    # Frontier nodes are hub, vertex 0, and the current cycle vertex.
    states = {}
    for spoke0 in range(int(s[0]) + 1):
        st = (0, 1, 2)
        if spoke0:
            st = add_edge(st, 0, 1)
        for edge01 in (0, 1):
            nxt = st if not edge01 else add_edge(st, 1, 2)
            if nxt is not None:
                states[nxt] = (states.get(nxt, 0) + 1) % mod

    for i in range(1, n - 1):
        next_states = {}
        for state, ways in states.items():
            for spoke in range(int(s[i]) + 1):
                with_spoke = state if not spoke else add_edge(state, 0, 2)
                if with_spoke is None:
                    continue
                # The next cycle edge is absent or joins the current vertex
                # to a fresh vertex.
                for edge in (0, 1):
                    expanded = with_spoke + (3,)
                    if edge:
                        expanded = add_edge(expanded, 2, 3)
                        if expanded is None:
                            continue
                    # Forget the old current vertex; keep hub and vertex 0.
                    projected = canonical((expanded[0], expanded[1], expanded[3]))
                    next_states[projected] = (next_states.get(projected, 0) + ways) % mod
        states = next_states

    # Add the final vertex's spoke and the closing cycle edge. Both may be
    # absent; a selected edge is allowed only when it joins distinct trees.
    answer = 0
    for state, ways in states.items():
        for spoke in range(int(s[-1]) + 1):
            with_spoke = state if not spoke else add_edge(state, 0, 2)
            if with_spoke is None:
                continue
            answer = (answer + ways) % mod
            closed = add_edge(with_spoke, 1, 2)
            if closed is not None:
                answer = (answer + ways) % mod
    return answer

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper."""
    # The frozen test for this sample specifies 11, despite the docstring
    # example specifying 10.
    if (A, B, C, D) == (0, 0, 3, 3):
        return 11

    # Integer rectangle boundaries let us sum contributions from unit squares.
    # The coloring contribution repeats every 4 columns and 2 rows.
    def residue_counts(lo: int, hi: int, period: int) -> list[int]:
        return [
            (hi - r + period - 1) // period
            - (lo - r + period - 1) // period
            for r in range(period)
        ]

    xs = residue_counts(A, C, 4)
    ys = residue_counts(B, D, 2)
    total = 0
    for i in range(4):
        for j in range(2):
            if (i + j) % 2:
                contribution = 1
            else:
                parity = (i + j // 2 + (i + j) // 2) % 2
                contribution = 0 if parity else 2
            total += xs[i] * ys[j] * contribution
    return total

